insert into passages (id, text, difficulty_level, b, active) values
('91f1c52f-3b7c-46a3-bc3e-c24711b38b53', 'Daniel works as a bus driver in a small town. He starts his shift very early, usually before six in the morning, when the streets are still quiet and empty. His first route takes him past the train station, where a few sleepy passengers wait for the bus to arrive. During the day, Daniel drives the same route again and again, stopping at each of the twelve stops along the way. He knows many of his regular passengers by name, and he always says good morning to them with a smile. In the afternoon, when school ends, the bus becomes crowded with children going home. Daniel says that although the job can be tiring, he enjoys meeting so many different people every single day.', 1, -2.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('a9347fca-5731-4a63-b223-cfea3c3b7189', 'sentence_completion', 'My mother ___ dinner in the kitchen right now.', NULL, '[{"id": "b", "text": "is cooking"}, {"id": "d", "text": "cook"}, {"id": "a", "text": "cooks"}, {"id": "c", "text": "cooked"}]'::jsonb, 0, '{"strategy": "right now = ממש עכשיו. פעולה שקורית ברגע הדיבור = הווה מתמשך.", "correct_reason": "is cooking = מבשלת. הווה מתמשך מתאים ל''right now''.", "options_analysis": ["נכון! is cooking = הווה מתמשך, מתאים ל''right now''", "cook = הווה פשוט ללא s — לא מתאים לגוף שלישי יחיד וגם לא ל''right now''", "cooks = הווה פשוט — לא מתאים ל''right now'' שדורש הווה מתמשך", "cooked = עבר — לא מתאים ל''right now''"]}', 0.6, -2.0, 0.25, 1, 'ai', NULL, true),
('96177b3a-0d15-463b-ac1d-125373217a22', 'sentence_completion', 'There are ___ books on the shelf than on the table.', NULL, '[{"id": "c", "text": "many"}, {"id": "a", "text": "more"}, {"id": "b", "text": "most"}, {"id": "d", "text": "much"}]'::jsonb, 1, '{"strategy": "than on the table = מאשר על השולחן. יש כאן השוואה בין שניים.", "correct_reason": "more = יותר. השוואה יחסית עם than.", "options_analysis": ["many = צורת יסוד — לא מתאימה להשוואה עם than", "נכון! more = השוואתי, מתאים ל-than", "most = עילית — לא מתאים להשוואה עם than", "much = משמש לשמות עצם לא ספירים, books הוא ספיר"]}', 0.83, -2.0, 0.25, 1, 'ai', NULL, true),
('6ce9c7cc-9a42-4b37-be3a-d7979699a921', 'sentence_completion', 'She ___ her keys yesterday and couldn''t find them anywhere.', NULL, '[{"id": "b", "text": "loses"}, {"id": "c", "text": "lose"}, {"id": "a", "text": "lost"}, {"id": "d", "text": "losing"}]'::jsonb, 2, '{"strategy": "yesterday = אתמול. עבר.", "correct_reason": "lost = איבדה. עבר של lose.", "options_analysis": ["הווה — לא מתאים ל''yesterday''", "צורת יסוד — לא מתאימה לעבר", "נכון! lost = עבר של lose, מתאים ל''yesterday''", "ing לבד ללא עזר לא תקין"]}', 0.53, -2.0, 0.25, 1, 'ai', NULL, true),
('f0f72f2c-eef6-4fe1-9b00-63bd95015ba2', 'sentence_completion', 'They ___ to the cinema tomorrow evening.', NULL, '[{"id": "d", "text": "go"}, {"id": "a", "text": "goes"}, {"id": "b", "text": "went"}, {"id": "c", "text": "are going"}]'::jsonb, 3, '{"strategy": "tomorrow evening = מחר בערב. תוכנית לעתיד = הווה מתמשך לעתיד מתוכנן.", "correct_reason": "are going = הולכים. הווה מתמשך מבטא תוכניות עתידיות.", "options_analysis": ["הווה פשוט — פחות טבעי לתיאור תוכנית עתידית ספציפית", "goes = גוף שלישי יחיד — לא מתאים ל-they", "went = עבר — לא מתאים ל''tomorrow evening''", "נכון! are going = הווה מתמשך מבטא תוכנית לעתיד"]}', 0.72, -2.0, 0.25, 1, 'ai', NULL, true),
('54529768-9bd0-452c-9a49-f28902c05306', 'sentence_completion', 'This is the ___ book I have ever read.', NULL, '[{"id": "a", "text": "best"}, {"id": "d", "text": "good"}, {"id": "c", "text": "better"}, {"id": "b", "text": "well"}]'::jsonb, 0, '{"strategy": "ever = אי פעם. השוואה בין יותר משניים = עילית (superlative).", "correct_reason": "best = הטוב ביותר. ''the...ever'' דורש עילית.", "options_analysis": ["נכון! best = עילית, מתאים ל''the...ever''", "good = צורת יסוד — לא מתאימה ל''the...ever''", "better = השוואתי — משמש בין שניים, לא ל''the...ever''", "well = תואר הפועל — לא מתאים לתיאור שם עצם כמו book"]}', 0.63, -2.0, 0.25, 1, 'ai', NULL, true),
('61afdaab-effa-49b3-9880-8c866150e3e3', 'sentence_completion', 'Look! The dog ___ across the street.', NULL, '[{"id": "d", "text": "run"}, {"id": "a", "text": "is running"}, {"id": "c", "text": "runs"}, {"id": "b", "text": "ran"}]'::jsonb, 1, '{"strategy": "Look! = תראה! מציין שמשהו קורה כרגע.", "correct_reason": "is running = רץ. הווה מתמשך מתאים לפעולה נראית כרגע.", "options_analysis": ["run = צורת יסוד — לא תקינה עם the dog כנושא יחיד", "נכון! is running = הווה מתמשך, מתאים ל''Look!'' שמצביע על עכשיו", "runs = הווה פשוט — לא מתאים לפעולה שקורית ממש עכשיו", "ran = עבר — לא מתאים לפעולה המתרחשת כרגע"]}', 0.69, -2.0, 0.25, 1, 'ai', NULL, true),
('2af77a6d-0052-4fbe-9328-c9aa14be1ad2', 'sentence_completion', 'He doesn''t like coffee, and I don''t like it ___.', NULL, '[{"id": "a", "text": "also"}, {"id": "c", "text": "neither"}, {"id": "b", "text": "either"}, {"id": "d", "text": "too"}]'::jsonb, 2, '{"strategy": "משפט שלילי + הסכמה = either, לא too.", "correct_reason": "either = גם לא. בשפט שלילי משתמשים ב-either ולא ב-too.", "options_analysis": ["also לא משמש בסוף משפט להסכמה שלילית", "neither ידרוש שינוי מבנה המשפט כולו", "נכון! either משמש בסוף משפט שלילי להסכמה", "too משמש במשפטים חיוביים, לא שליליים"]}', 0.6, -2.0, 0.25, 1, 'ai', NULL, true),
('e340de1b-addd-473f-aab8-1c732c0c0440', 'sentence_completion', 'The children ___ their homework before they watched TV last night.', NULL, '[{"id": "b", "text": "finish"}, {"id": "c", "text": "finishes"}, {"id": "a", "text": "finished"}, {"id": "d", "text": "had finished"}]'::jsonb, 3, '{"strategy": "before...last night = לפני...אתמול בלילה. שתי פעולות בעבר, אחת הושלמה לפני השנייה = past perfect.", "correct_reason": "had finished = סיימו. פעולה שהושלמה לפני פעולה אחרת בעבר.", "options_analysis": ["הווה — לא מתאים ל''last night''", "גוף שלישי יחיד — לא מתאים ל-children שהוא רבים", "עבר פשוט — לא מדגיש שהפעולה הושלמה לפני האחרת", "נכון! had finished = past perfect, מציין השלמה לפני פעולה אחרת בעבר"]}', 0.85, -2.0, 0.25, 1, 'ai', NULL, true),
('0f108d99-412a-4abc-8957-a3de4a86671d', 'sentence_completion', 'Would you like ___ tea or coffee?', NULL, '[{"id": "a", "text": "some"}, {"id": "b", "text": "any"}, {"id": "d", "text": "an"}, {"id": "c", "text": "a"}]'::jsonb, 0, '{"strategy": "בהצעה מנומסת (offer) משתמשים ב-some גם בשאלה.", "correct_reason": "some = קצת. בהצעות מנומסות (Would you like...?) משתמשים ב-some.", "options_analysis": ["נכון! some משמש בהצעות מנומסות גם בצורת שאלה", "any משמש לרוב בשאלות רגילות ושלילה, לא בהצעות מנומסות", "an לא מתאים לשם עצם לא ספיר כמו tea/coffee", "a לא מתאים לשם עצם לא ספיר כמו tea/coffee"]}', 0.86, -2.0, 0.25, 1, 'ai', NULL, true),
('2ca00317-4d7a-483e-8905-ec8501e582f9', 'sentence_completion', 'I have ___ finished my homework, so I can go outside now.', NULL, '[{"id": "b", "text": "ago"}, {"id": "c", "text": "just"}, {"id": "a", "text": "since"}, {"id": "d", "text": "yet"}]'::jsonb, 1, '{"strategy": "so I can go outside now = אז אני יכול לצאת עכשיו. פעולה שהושלמה ממש לאחרונה.", "correct_reason": "just = ממש עכשיו/זה עתה. משמש בהווה מושלם לפעולה שהושלמה לאחרונה.", "options_analysis": ["ago משמש עם עבר פשוט, לא הווה מושלם", "נכון! just = זה עתה, מתאים להווה מושלם לפעולה שהושלמה לאחרונה", "since משמש לנקודת זמן, לא לתיאור ''זה עתה''", "yet משמש בעיקר בשלילה ובשאלה, לא במשפט חיובי כזה"]}', 0.7, -2.0, 0.25, 1, 'ai', NULL, true),
('ddc2dbdd-2404-4514-972e-907179a85d7c', 'sentence_completion', 'She is interested ___ learning French.', NULL, '[{"id": "b", "text": "for"}, {"id": "a", "text": "at"}, {"id": "c", "text": "in"}, {"id": "d", "text": "on"}]'::jsonb, 2, '{"strategy": "interested + preposition = צירוף קבוע. ''interested in'' הוא הצירוף הנכון.", "correct_reason": "in = ב-. ''interested in'' הוא הצירוף התקני.", "options_analysis": ["for לא הצירוף הנכון עם interested", "at לא הצירוף הנכון עם interested", "נכון! interested in = הצירוף התקני", "on לא הצירוף הנכון עם interested"]}', 0.64, -2.0, 0.25, 1, 'ai', NULL, true),
('f80a03b6-4c59-4450-9dae-e714df8290a2', 'sentence_completion', 'The weather is ___ cold today that we decided to stay home.', NULL, '[{"id": "a", "text": "very"}, {"id": "d", "text": "too"}, {"id": "b", "text": "such"}, {"id": "c", "text": "so"}]'::jsonb, 3, '{"strategy": "...that we decided = ש...החלטנו. תבנית so + adjective + that מבטאת תוצאה.", "correct_reason": "so = כל כך. so + תואר + that מבטא תוצאה.", "options_analysis": ["very לא מתחבר עם that בתבנית תוצאה", "too לא מתחבר עם that באותה תבנית", "such משמש עם שם עצם, לא עם תואר לבד", "נכון! so + adjective + that = תבנית תוצאה תקנית"]}', 0.74, -2.0, 0.25, 1, 'ai', NULL, true),
('2836276c-88f9-4935-9279-c4fb8b7e50dd', 'restatement', 'This shirt is cheaper than that one.', NULL, '[{"id": "b", "text": "That shirt costs more money than this one."}, {"id": "d", "text": "This shirt is the most expensive shirt in the store."}, {"id": "a", "text": "This shirt costs more money than that one."}, {"id": "c", "text": "Both shirts cost exactly the same."}]'::jsonb, 0, '{"strategy": "cheaper than = יותר זול מ-. השוואה בין שניים.", "correct_reason": "אותה משמעות: אם החולצה הזו זולה יותר, האחרת יקרה יותר.", "options_analysis": ["נכון! אותה משמעות: החולצה השנייה יקרה יותר", "לא נאמר במקור — אין מידע על שאר החנות", "הפוך — סותר ''this shirt is cheaper''", "סותר את ההשוואה — הן לא שוות"]}', 0.54, -2.0, 0.25, 1, 'ai', NULL, true),
('313a0a66-355a-4fc0-8822-c477129c301c', 'restatement', 'He always arrives at work before 9 AM.', NULL, '[{"id": "b", "text": "He does not have a job."}, {"id": "a", "text": "He gets to work every day before nine o''clock in the morning."}, {"id": "d", "text": "He arrives at work exactly at 9 AM."}, {"id": "c", "text": "He never arrives at work before 9 AM."}]'::jsonb, 1, '{"strategy": "always...before 9 AM = תמיד...לפני 9. תיאור הרגל קבוע.", "correct_reason": "אותה משמעות בדיוק: מגיע לעבודה כל יום לפני השעה תשע.", "options_analysis": ["סותר את קיום העבודה שהוזכרה", "נכון! אותה משמעות בדיוק: מגיע כל יום לפני 9", "סותר ''before 9 AM'' — הוא מגיע לפני, לא בדיוק ב-9", "הפוך — סותר ''always arrives...before 9 AM''"]}', 0.65, -2.0, 0.25, 1, 'ai', NULL, true),
('61e7a7de-b8ef-416e-814e-789760050f54', 'restatement', 'The library is closed on Sundays.', NULL, '[{"id": "b", "text": "The library is only open on Sundays."}, {"id": "c", "text": "The library has no fixed schedule."}, {"id": "d", "text": "On Sundays, the library does not open its doors."}, {"id": "a", "text": "The library is open every day including Sunday."}]'::jsonb, 2, '{"strategy": "closed on Sundays = סגורה בימי ראשון.", "correct_reason": "אותה משמעות בדיוק: בימי ראשון הספרייה לא פותחת דלתות.", "options_analysis": ["הפוך — סותר ''closed on Sundays'' (סגורה, לא פתוחה רק אז)", "סותר את קיום לוח הזמנים הקבוע שתואר", "נכון! אותה משמעות בדיוק: בימי ראשון הספרייה לא פתוחה", "הפוך — סותר ''closed on Sundays''"]}', 0.85, -2.0, 0.25, 1, 'ai', NULL, true),
('648b408d-196a-4371-b152-f2e64aadaa13', 'restatement', 'My grandmother taught me how to bake bread.', NULL, '[{"id": "c", "text": "My grandmother never baked bread."}, {"id": "a", "text": "I already knew how to bake bread before my grandmother taught me."}, {"id": "d", "text": "I taught my grandmother how to bake bread."}, {"id": "b", "text": "My grandmother showed me the way to make bread."}]'::jsonb, 3, '{"strategy": "taught me how to bake = לימדה אותי איך לאפות.", "correct_reason": "אותה משמעות בדיוק: הראתה לי איך להכין לחם.", "options_analysis": ["סותר ''taught me how to bake bread'' — היא כן אפתה", "סותר את מטרת הלימוד שתוארה", "הפוך — הכיוון הפוך: הסבתא לימדה, לא להפך", "נכון! אותה משמעות בדיוק: הראתה לי איך להכין לחם"]}', 0.84, -2.0, 0.25, 1, 'ai', NULL, true),
('605d17da-ecb8-4fd6-af54-8ca9e287600d', 'restatement', 'The park is located next to the school.', NULL, '[{"id": "c", "text": "The park is right beside the school."}, {"id": "d", "text": "There is no park near the school."}, {"id": "a", "text": "The park is far away from the school."}, {"id": "b", "text": "The school is inside the park."}]'::jsonb, 0, '{"strategy": "next to = ליד. מיקום סמוך.", "correct_reason": "אותה משמעות בדיוק: הפארק ממש ליד בית הספר.", "options_analysis": ["נכון! אותה משמעות בדיוק: ממש ליד בית הספר", "סותר את קיום הפארק שתואר", "הפוך — ''far away'' סותר ''next to''", "לא נאמר במקור — ''next to'' לא אומר ''inside''"]}', 0.64, -2.0, 0.25, 1, 'ai', NULL, true),
('dbb917dd-5941-4f78-be81-a6f3796dffd9', 'restatement', 'We should leave now if we don''t want to be late.', NULL, '[{"id": "a", "text": "We have already left and are not late."}, {"id": "c", "text": "If we want to avoid being late, we need to leave right now."}, {"id": "d", "text": "We are already late, so there''s no point leaving."}, {"id": "b", "text": "We can leave whenever we want without any consequences."}]'::jsonb, 1, '{"strategy": "should leave now if...late = צריכים לצאת עכשיו אם...מאחרים. תנאי.", "correct_reason": "אותה משמעות בדיוק: כדי להימנע מאיחור, צריך לצאת עכשיו.", "options_analysis": ["סותר ''we should leave now'' — עדיין לא יצאו", "נכון! אותה משמעות בדיוק: כדי להימנע מאיחור, לצאת עכשיו", "הפוך — ''don''t want to be late'' מרמז שעדיין לא מאחרים", "הפוך — סותר את הדחיפות שבמשפט המקורי"]}', 0.54, -2.0, 0.25, 1, 'ai', NULL, true),
('6f95ea59-26aa-4bf2-bffa-177497796303', 'restatement', 'The soup tastes delicious.', NULL, '[{"id": "a", "text": "The soup has no taste at all."}, {"id": "c", "text": "No one has tasted the soup yet."}, {"id": "d", "text": "The soup has a very good taste."}, {"id": "b", "text": "The soup tastes terrible."}]'::jsonb, 2, '{"strategy": "tastes delicious = טעים.", "correct_reason": "אותה משמעות בדיוק: יש לו טעם טוב מאוד.", "options_analysis": ["הפוך — סותר את קיום הטעם הטוב שתואר", "סותר ''tastes delicious'' — מישהו כן טעם אותו", "נכון! אותה משמעות בדיוק: טעם טוב מאוד", "הפוך — ''terrible'' סותר ''delicious''"]}', 0.84, -2.0, 0.25, 1, 'ai', NULL, true),
('780355b9-474e-4336-b9c6-6cb8a67efc12', 'restatement', 'She works part-time at a bookstore.', NULL, '[{"id": "b", "text": "She does not work at all."}, {"id": "d", "text": "She owns the bookstore where she works."}, {"id": "c", "text": "She works full-time at a bookstore."}, {"id": "a", "text": "She works at a bookstore for only part of the week."}]'::jsonb, 3, '{"strategy": "part-time = חלקית. פחות משעות מלאות.", "correct_reason": "אותה משמעות בדיוק: עובדת בחנות ספרים רק חלק מהשבוע.", "options_analysis": ["סותר ''works part-time'' — היא כן עובדת", "לא נאמר במקור — אין מידע על בעלות על החנות", "הפוך — ''full-time'' סותר ''part-time''", "נכון! אותה משמעות בדיוק: עובדת רק חלק מהשבוע"]}', 0.85, -2.0, 0.25, 1, 'ai', NULL, true),
('04bef1c6-caa7-4de0-adec-f99942c1d5b9', 'restatement', 'The movie starts at 8 o''clock sharp.', NULL, '[{"id": "c", "text": "The movie begins exactly at eight o''clock."}, {"id": "b", "text": "The movie has no specific start time."}, {"id": "a", "text": "The movie already finished before 8 o''clock."}, {"id": "d", "text": "The movie starts sometime after 8 o''clock."}]'::jsonb, 0, '{"strategy": "starts at 8 sharp = מתחיל בדיוק ב-8.", "correct_reason": "אותה משמעות בדיוק: מתחיל בדיוק בשעה שמונה.", "options_analysis": ["נכון! אותה משמעות בדיוק: מתחיל בדיוק בשעה שמונה", "הפוך — סותר ''starts at 8 o''clock sharp''", "סותר ''starts at 8'' — הסרט עוד לא התחיל, לא הסתיים", "סותר ''sharp'' שמציין דיוק, לא ''sometime after''"]}', 0.67, -2.0, 0.25, 1, 'ai', NULL, true),
('4aea7f62-3a28-4db6-a381-9deefb887fca', 'restatement', 'My favorite season is winter because I love snow.', NULL, '[{"id": "d", "text": "I have no favorite season at all."}, {"id": "c", "text": "I like winter best since I really enjoy the snow."}, {"id": "a", "text": "My favorite season is summer because I love the sun."}, {"id": "b", "text": "I dislike winter and all types of weather."}]'::jsonb, 1, '{"strategy": "favorite...because = מועדפת...כי. סיבה-העדפה.", "correct_reason": "אותה משמעות בדיוק: אוהבת הכי את החורף כי נהנית מהשלג.", "options_analysis": ["סותר את קיום העונה המועדפת שתוארה", "נכון! אותה משמעות בדיוק: אוהבת הכי את החורף בגלל השלג", "הפוך — ''summer'' סותר ''winter''", "הפוך — סותר ''I love snow''"]}', 0.55, -2.0, 0.25, 1, 'ai', NULL, true),
('b44caa25-bffe-4c4a-b5bb-bc5c9c9376b4', 'restatement', 'The teacher gave the students a lot of homework last night.', NULL, '[{"id": "c", "text": "The students did not receive any homework."}, {"id": "d", "text": "The teacher gave the students very little homework."}, {"id": "a", "text": "The students received a large amount of homework from the teacher last night."}, {"id": "b", "text": "The teacher never gives homework."}]'::jsonb, 2, '{"strategy": "gave...a lot of homework = נתן...הרבה שיעורי בית.", "correct_reason": "אותה משמעות בדיוק: התלמידים קיבלו כמות גדולה של שיעורי בית.", "options_analysis": ["הפוך — סותר ''a lot of homework''", "הפוך — ''very little'' סותר ''a lot of''", "נכון! אותה משמעות בדיוק: כמות גדולה של שיעורי בית", "הפוך — סותר ''gave the students...homework''"]}', 0.78, -2.0, 0.25, 1, 'ai', NULL, true),
('3d427d54-f004-4b6a-b2e4-739d2a7ff4d8', 'restatement', 'He apologized for being late to the meeting.', NULL, '[{"id": "c", "text": "He was proud of arriving late to the meeting."}, {"id": "b", "text": "He refused to attend the meeting at all."}, {"id": "a", "text": "He arrived early to the meeting."}, {"id": "d", "text": "He said sorry because he arrived late for the meeting."}]'::jsonb, 3, '{"strategy": "apologized for being late = התנצל על האיחור.", "correct_reason": "אותה משמעות בדיוק: אמר סליחה כי הגיע מאוחר לפגישה.", "options_analysis": ["הפוך — ''proud'' סותר ''apologized''", "סותר ''to the meeting'' — הוא כן הגיע לפגישה", "הפוך — ''early'' סותר ''late''", "נכון! אותה משמעות בדיוק: אמר סליחה כי הגיע מאוחר"]}', 0.63, -2.0, 0.25, 1, 'ai', NULL, true),
('9252c3d0-c76f-4fd8-ab79-a5b0c9b5813a', 'reading_comprehension', 'What is Daniel''s job?', '91f1c52f-3b7c-46a3-bc3e-c24711b38b53', '[{"id": "a", "text": "He is a bus driver"}, {"id": "d", "text": "He is a shop owner"}, {"id": "c", "text": "He is a train conductor"}, {"id": "b", "text": "He is a school teacher"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את תפקידו של דניאל בפסקה.", "correct_reason": "הפסקה אומרת: ''Daniel works as a bus driver''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה כלל", "לא נאמר בפסקה — הוא נוסע ליד תחנת רכבת, לא עובד בה", "לא נאמר בפסקה כלל"]}', 0.6, -2.0, 0.25, 1, 'ai', NULL, true),
('1c0f3da9-c963-435d-9a47-7ecc8d01090c', 'reading_comprehension', 'How many stops does Daniel''s route have?', '91f1c52f-3b7c-46a3-bc3e-c24711b38b53', '[{"id": "d", "text": "It has no stops"}, {"id": "a", "text": "Twelve"}, {"id": "b", "text": "Six"}, {"id": "c", "text": "Two"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את מספר התחנות בפסקה.", "correct_reason": "הפסקה אומרת: ''stopping at each of the twelve stops along the way''.", "options_analysis": ["סותר את הפסקה שמתארת תחנות בדרך", "נכון! נאמר במפורש בפסקה", "זו שעת תחילת המשמרת, לא מספר התחנות", "לא נאמר בפסקה"]}', 0.61, -2.0, 0.25, 1, 'ai', NULL, true),
('f5f94fd3-2905-4fb6-bd98-1a6d070bad5f', 'reading_comprehension', 'According to the passage, when does the bus become crowded?', '91f1c52f-3b7c-46a3-bc3e-c24711b38b53', '[{"id": "d", "text": "It is never crowded"}, {"id": "c", "text": "At midnight"}, {"id": "a", "text": "In the afternoon when school ends"}, {"id": "b", "text": "Early in the morning"}]'::jsonb, 2, '{"strategy": "שאלת פרט — חפש מתי האוטובוס מתמלא.", "correct_reason": "הפסקה אומרת: ''In the afternoon, when school ends, the bus becomes crowded with children going home''.", "options_analysis": ["סותר את הפסקה שמתארת מתי האוטובוס מתמלא", "לא נאמר בפסקה כלל", "נכון! נאמר במפורש בפסקה", "סותר את הפסקה שמתארת רחובות שקטים וריקים בבוקר"]}', 0.76, -2.0, 0.25, 1, 'ai', NULL, true),
('edf3b199-ef95-42ea-8b20-04ba53c8728c', 'reading_comprehension', 'What does Daniel say he enjoys about his job?', '91f1c52f-3b7c-46a3-bc3e-c24711b38b53', '[{"id": "b", "text": "Working only a few hours a day"}, {"id": "c", "text": "Driving alone with no passengers"}, {"id": "d", "text": "Never talking to anyone"}, {"id": "a", "text": "Meeting many different people every day"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש מה דניאל אומר שהוא נהנה ממנו.", "correct_reason": "הפסקה אומרת: ''he enjoys meeting so many different people every single day''.", "options_analysis": ["לא נאמר בפסקה — נאמר שהעבודה יכולה להיות מעייפת", "הפוך — הפסקה מתארת נוסעים רבים, לא נסיעה לבד", "הפוך — הפסקה אומרת שהוא תמיד אומר בוקר טוב לנוסעים", "נכון! נאמר במפורש בפסקה"]}', 0.68, -2.0, 0.25, 1, 'ai', NULL, true);